pub struct Header {
    pub name: String,
}

pub fn parse(input: &str) -> Header {
    Header { name: input[0..1].to_string() }
}

pub fn describe(h: &Header) -> String {
    format!("header {}", h.name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_name() {
        assert_eq!(parse("ab").name, "a");
    }
}

